CREATE FUNCTION public.get_category_performance(p_start_date date, p_end_date date, p_branch_ids integer[] DEFAULT NULL::integer[]) RETURNS TABLE(category character varying, total_revenue numeric, total_units_sold bigint, transaction_count bigint, avg_price numeric, revenue_share numeric, rank_position bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH category_totals AS (
        SELECT 
            dcs.category,
            SUM(dcs.revenue) AS total_revenue,
            SUM(dcs.units_sold) AS total_units,
            SUM(dcs.transaction_count) AS total_transactions,
            AVG(dcs.avg_price) AS avg_price
        FROM daily_category_summary dcs
        WHERE dcs.summary_date BETWEEN p_start_date AND p_end_date
          AND (p_branch_ids IS NULL OR dcs.branch_id = ANY(p_branch_ids))
        GROUP BY dcs.category
    ),
    overall_revenue AS (
        SELECT SUM(total_revenue) AS grand_total FROM category_totals
    )
    SELECT 
        ct.category,
        ct.total_revenue,
        ct.total_units,
        ct.total_transactions,
        ct.avg_price,
        ROUND((ct.total_revenue / NULLIF(orv.grand_total, 0)) * 100, 2),
        ROW_NUMBER() OVER (ORDER BY ct.total_revenue DESC)
    FROM category_totals ct
    CROSS JOIN overall_revenue orv
    ORDER BY ct.total_revenue DESC;
END;
$$;


