CREATE FUNCTION public.get_customer_insights(p_start_date date, p_end_date date, p_branch_ids integer[] DEFAULT NULL::integer[]) RETURNS TABLE(loyalty_tier character varying, age_group character varying, religion character varying, customer_count bigint, total_spend numeric, avg_spend_per_customer numeric, spend_share numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH customer_data AS (
        SELECT 
            dcs.loyalty_tier,
            dcs.age_group,
            dcs.religion,
            SUM(dcs.customer_count) AS total_customers,
            SUM(dcs.total_spend) AS total_spend,
            AVG(dcs.avg_spend_per_customer) AS avg_spend
        FROM daily_customer_summary dcs
        WHERE dcs.summary_date BETWEEN p_start_date AND p_end_date
          AND (p_branch_ids IS NULL OR dcs.branch_id = ANY(p_branch_ids))
        GROUP BY dcs.loyalty_tier, dcs.age_group, dcs.religion
    ),
    overall_spend AS (
        SELECT SUM(total_spend) AS grand_total FROM customer_data
    )
    SELECT 
        cd.loyalty_tier,
        cd.age_group,
        cd.religion,
        cd.total_customers,
        cd.total_spend,
        cd.avg_spend,
        ROUND((cd.total_spend / NULLIF(os.grand_total, 0)) * 100, 2)
    FROM customer_data cd
    CROSS JOIN overall_spend os
    ORDER BY cd.total_spend DESC;
END;
$$;


