CREATE FUNCTION public.get_sales_summary(p_start_date date, p_end_date date, p_branch_ids integer[] DEFAULT NULL::integer[], p_group_by character varying DEFAULT 'day'::character varying) RETURNS TABLE(period_date date, period_label character varying, branch_id integer, branch_name character varying, region character varying, total_revenue numeric, total_transactions bigint, avg_basket numeric, unique_customers integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF p_group_by = 'day' THEN
        RETURN QUERY
        SELECT 
            dss.summary_date,
            TO_CHAR(dss.summary_date, 'YYYY-MM-DD'),
            dss.branch_id,
            dss.branch_name,
            dss.region,
            SUM(dss.total_revenue),
            SUM(dss.transaction_count),
            AVG(dss.avg_basket_value),
            SUM(dss.unique_customers)
        FROM daily_sales_summary dss
        WHERE dss.summary_date BETWEEN p_start_date AND p_end_date
          AND (p_branch_ids IS NULL OR dss.branch_id = ANY(p_branch_ids))
        GROUP BY dss.summary_date, dss.branch_id, dss.branch_name, dss.region
        ORDER BY dss.summary_date, dss.branch_id;
    
    ELSIF p_group_by = 'week' THEN
        RETURN QUERY
        SELECT 
            DATE_TRUNC('week', dss.summary_date)::DATE,
            'Week ' || EXTRACT(WEEK FROM dss.summary_date) || ', ' || EXTRACT(YEAR FROM dss.summary_date),
            dss.branch_id,
            dss.branch_name,
            dss.region,
            SUM(dss.total_revenue),
            SUM(dss.transaction_count),
            AVG(dss.avg_basket_value),
            SUM(dss.unique_customers)
        FROM daily_sales_summary dss
        WHERE dss.summary_date BETWEEN p_start_date AND p_end_date
          AND (p_branch_ids IS NULL OR dss.branch_id = ANY(p_branch_ids))
        GROUP BY DATE_TRUNC('week', dss.summary_date), dss.branch_id, dss.branch_name, dss.region
        ORDER BY DATE_TRUNC('week', dss.summary_date), dss.branch_id;
    
    ELSIF p_group_by = 'month' THEN
        RETURN QUERY
        SELECT 
            DATE_TRUNC('month', dss.summary_date)::DATE,
            TO_CHAR(dss.summary_date, 'Mon YYYY'),
            dss.branch_id,
            dss.branch_name,
            dss.region,
            SUM(dss.total_revenue),
            SUM(dss.transaction_count),
            AVG(dss.avg_basket_value),
            SUM(dss.unique_customers)
        FROM daily_sales_summary dss
        WHERE dss.summary_date BETWEEN p_start_date AND p_end_date
          AND (p_branch_ids IS NULL OR dss.branch_id = ANY(p_branch_ids))
        GROUP BY DATE_TRUNC('month', dss.summary_date), dss.branch_id, dss.branch_name, dss.region
        ORDER BY DATE_TRUNC('month', dss.summary_date), dss.branch_id;
    END IF;
END;
$$;


