--
-- TOC entry 274 (class 1255 OID 345103)
-- Name: populate_daily_category_summary(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.populate_daily_category_summary(p_date date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows_affected INTEGER;
BEGIN
        summary_date, branch_id, category,
        revenue, units_sold, transaction_count, avg_price, discount_amount
    )
    SELECT
        p_date,
        t.branch_id,
        p.category,
        SUM(ti.line_total_lkr),
        SUM(ti.quantity),
        COUNT(DISTINCT t.txn_id),
        AVG(ti.unit_price_lkr),
        SUM(t.discount_lkr * (ti.line_total_lkr / NULLIF(t.total_value_lkr, 0)))
    FROM transactions t
    JOIN transaction_items ti ON ti.txn_id = t.txn_id
    JOIN products p ON p.product_id = ti.product_id
    WHERE t.txn_date = p_date
    GROUP BY t.branch_id, p.category
    ON CONFLICT (summary_date, branch_id, category)
    DO UPDATE SET
        revenue = EXCLUDED.revenue,
        units_sold = EXCLUDED.units_sold,
        transaction_count = EXCLUDED.transaction_count,
        avg_price = EXCLUDED.avg_price,
        discount_amount = EXCLUDED.discount_amount;
    
    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
    RETURN v_rows_affected;
END;
$$;


ALTER FUNCTION public.populate_daily_category_summary(p_date date) OWNER TO postgres;

