CREATE FUNCTION public.populate_daily_customer_summary(p_date date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows_affected INTEGER;
BEGIN
        summary_date, branch_id, loyalty_tier, age_group, religion,
        customer_count, total_spend, avg_spend_per_customer
    )
    SELECT
        p_date,
        t.branch_id,
        c.loyalty_tier,
        c.age_group,
        c.religion,
        COUNT(DISTINCT t.customer_id),
        SUM(t.total_value_lkr),
        AVG(t.total_value_lkr)
