    JOIN customers c ON c.customer_id = t.customer_id
    WHERE t.txn_date = p_date
    GROUP BY t.branch_id, c.loyalty_tier, c.age_group, c.religion
    ON CONFLICT (summary_date, branch_id, loyalty_tier, age_group, religion)
    DO UPDATE SET
        customer_count = EXCLUDED.customer_count,
        total_spend = EXCLUDED.total_spend,
        avg_spend_per_customer = EXCLUDED.avg_spend_per_customer;
    
    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
    RETURN v_rows_affected;
END;
$$;


