-- Name: populate_daily_product_summary(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.populate_daily_product_summary(p_date date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows_affected INTEGER;
BEGIN
    -- Delete existing records for the date to avoid duplicates
    DELETE FROM daily_product_summary 
    WHERE summary_date = p_date;
    
    -- Insert fresh product-level summary data
        summary_date,
        branch_id,
        product_id,
        product_name,
        category,
        sub_category,
        brand,
        units_sold,
        revenue,
        avg_price,
        discount_amount,
        unique_customers
    )
    SELECT
        p_date,
        t.branch_id,
        p.product_id,
        p.product_name,
        p.category,
        p.sub_category,
        p.brand,
        SUM(ti.quantity) AS units_sold,
        SUM(ti.line_total_lkr) AS revenue,
        AVG(ti.unit_price_lkr) AS avg_price,
        SUM(t.discount_lkr * (ti.line_total_lkr / NULLIF(t.total_value_lkr, 0))) AS discount_amount,
        COUNT(DISTINCT t.customer_id) AS unique_customers
    FROM transactions t
    JOIN transaction_items ti ON ti.txn_id = t.txn_id
    JOIN products p ON p.product_id = ti.product_id
    WHERE t.txn_date = p_date
    GROUP BY 
        t.branch_id, 
        p.product_id, 
        p.product_name, 
        p.category, 
        p.sub_category, 
        p.brand;
    
    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
    RETURN v_rows_affected;
END;
$$;


ALTER FUNCTION public.populate_daily_product_summary(p_date date) OWNER TO postgres;

--
-- TOC entry 268 (class 1255 OID 345096)
-- Name: populate_daily_sales_summary(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.populate_daily_sales_summary(p_date date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows_affected INTEGER;
BEGIN
    -- Upsert daily sales summary
        summary_date, branch_id, branch_name, region, city,
        total_revenue, total_discount, total_items_sold, transaction_count,
        unique_customers, avg_basket_value, avg_items_per_basket,
        cash_revenue, card_revenue, qr_revenue, voucher_revenue,
        morning_revenue, afternoon_revenue, evening_revenue, night_revenue
    )
    SELECT
        p_date,
        b.branch_id,
        b.branch_name,
        b.region,
        b.city,
        COALESCE(SUM(t.total_value_lkr), 0),
        COALESCE(SUM(t.discount_lkr), 0),
        COALESCE(SUM(t.num_items), 0),
        COUNT(DISTINCT t.txn_id),
        COUNT(DISTINCT t.customer_id),
        COALESCE(AVG(t.total_value_lkr), 0),
        COALESCE(AVG(t.num_items), 0),
        COALESCE(SUM(CASE WHEN t.payment_method = 'Cash' THEN t.total_value_lkr ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN t.payment_method = 'Card' THEN t.total_value_lkr ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN t.payment_method = 'QR Pay' THEN t.total_value_lkr ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN t.payment_method = 'Voucher' THEN t.total_value_lkr ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN t.time_of_day = 'Morning' THEN t.total_value_lkr ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN t.time_of_day = 'Afternoon' THEN t.total_value_lkr ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN t.time_of_day = 'Evening' THEN t.total_value_lkr ELSE 0 END), 0),
        COALESCE(SUM(CASE WHEN t.time_of_day = 'Night' THEN t.total_value_lkr ELSE 0 END), 0)
    FROM branches b
    LEFT JOIN transactions t ON t.branch_id = b.branch_id AND t.txn_date = p_date
    GROUP BY b.branch_id, b.branch_name, b.region, b.city
    ON CONFLICT (summary_date, branch_id) 
    DO UPDATE SET
        total_revenue = EXCLUDED.total_revenue,
        total_discount = EXCLUDED.total_discount,
        total_items_sold = EXCLUDED.total_items_sold,
        transaction_count = EXCLUDED.transaction_count,
        unique_customers = EXCLUDED.unique_customers,
        avg_basket_value = EXCLUDED.avg_basket_value,
        avg_items_per_basket = EXCLUDED.avg_items_per_basket,
        cash_revenue = EXCLUDED.cash_revenue,
        card_revenue = EXCLUDED.card_revenue,
        qr_revenue = EXCLUDED.qr_revenue,
        voucher_revenue = EXCLUDED.voucher_revenue,
        morning_revenue = EXCLUDED.morning_revenue,
        afternoon_revenue = EXCLUDED.afternoon_revenue,
        evening_revenue = EXCLUDED.evening_revenue,
        night_revenue = EXCLUDED.night_revenue,
        updated_at = CURRENT_TIMESTAMP;
    
    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
    RETURN v_rows_affected;
END;
$$;


ALTER FUNCTION public.populate_daily_sales_summary(p_date date) OWNER TO postgres;

--
-- TOC entry 270 (class 1255 OID 345098)
-- Name: populate_hourly_summary(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.populate_hourly_summary(p_date date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_rows_affected INTEGER;
BEGIN
        summary_date, hour_of_day, branch_id, day_of_week,
        transaction_count, revenue, items_sold
    )
    SELECT
        p_date,
        EXTRACT(HOUR FROM t.txn_time)::INTEGER,
        t.branch_id,
        t.day_of_week,
        COUNT(DISTINCT t.txn_id),
        SUM(t.total_value_lkr),
        SUM(t.num_items)
    FROM (
        SELECT 
            txn_id, branch_id, day_of_week, total_value_lkr, num_items,
            -- Simulating transaction time since not in original schema
            (CASE time_of_day
                WHEN 'Morning' THEN '09:00:00'::TIME
                WHEN 'Afternoon' THEN '13:00:00'::TIME
                WHEN 'Evening' THEN '18:00:00'::TIME
                WHEN 'Night' THEN '21:00:00'::TIME
            END) AS txn_time
        FROM transactions
        WHERE txn_date = p_date
    ) t
    GROUP BY t.branch_id, EXTRACT(HOUR FROM t.txn_time), t.day_of_week
    ON CONFLICT (summary_date, hour_of_day, branch_id)
    DO UPDATE SET
        transaction_count = EXCLUDED.transaction_count,
        revenue = EXCLUDED.revenue,
        items_sold = EXCLUDED.items_sold;
    
    GET DIAGNOSTICS v_rows_affected = ROW_COUNT;
    RETURN v_rows_affected;
END;
$$;


ALTER FUNCTION public.populate_hourly_summary(p_date date) OWNER TO postgres;

--
-- TOC entry 264 (class 1255 OID 344978)
-- Name: sp_get_dashboard_charts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_get_dashboard_charts() RETURNS TABLE(chart_id text, label text, value1 numeric, value2 numeric, value3 numeric)
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Monthly Revenue
    RETURN QUERY
    SELECT 'monthly_revenue'::TEXT,
           TO_CHAR(txn_date,'Mon')::TEXT,
           ROUND(SUM(total_value_lkr)::NUMERIC, 2),
           0::NUMERIC, 0::NUMERIC
    FROM transactions
    GROUP BY EXTRACT(MONTH FROM txn_date), TO_CHAR(txn_date,'Mon')
    ORDER BY EXTRACT(MONTH FROM txn_date);

    -- Category Revenue
    RETURN QUERY
    SELECT 'category_revenue'::TEXT,
           category::TEXT,
           ROUND(SUM(revenue_ytd)::NUMERIC, 2),
           0::NUMERIC, 0::NUMERIC
    FROM products
    GROUP BY category
    ORDER BY SUM(revenue_ytd) DESC;

    -- Branch Revenue
    RETURN QUERY
    SELECT 'branch_revenue'::TEXT,
           b.branch_name::TEXT,
           ROUND(COALESCE(SUM(t.total_value_lkr), 0)::NUMERIC, 2),
           0::NUMERIC, 0::NUMERIC
    FROM branches b
    LEFT JOIN transactions t ON t.branch_id = b.branch_id
    GROUP BY b.branch_id, b.branch_name
    ORDER BY SUM(t.total_value_lkr) DESC NULLS LAST;

    -- Loyalty Cart
    RETURN QUERY
    SELECT 'loyalty_cart'::TEXT,
           loyalty_tier::TEXT,
           ROUND(AVG(avg_cart_size_lkr)::NUMERIC, 2),
           0::NUMERIC, 0::NUMERIC
    FROM customers
    GROUP BY loyalty_tier
    ORDER BY AVG(avg_cart_size_lkr) DESC;

    -- Revenue vs GP by Category (calculated from actual transactions)
    RETURN QUERY
    WITH category_metrics AS (
        SELECT 
            p.category,
            SUM(ti.line_total_lkr) AS revenue,
            SUM(ti.quantity * COALESCE(po.unit_cost_lkr, p.cost_price_lkr, 0)) AS cogs
        FROM products p
        LEFT JOIN transaction_items ti ON p.product_id = ti.product_id
        LEFT JOIN transactions t ON ti.txn_id = t.txn_id
        LEFT JOIN purchase_orders po ON p.product_id = po.product_id
        GROUP BY p.category
    )
    SELECT 'revenue_vs_gp'::TEXT,
           cm.category::TEXT,
           ROUND(COALESCE(cm.revenue, 0)::NUMERIC, 2),
           ROUND(COALESCE((cm.revenue - cm.cogs), 0)::NUMERIC, 2),
           0::NUMERIC
    FROM category_metrics cm
    WHERE cm.category IS NOT NULL
    ORDER BY COALESCE(cm.revenue, 0) DESC
    LIMIT 8;
END;
$$;


ALTER FUNCTION public.sp_get_dashboard_charts() OWNER TO postgres;

--
-- TOC entry 266 (class 1255 OID 344977)
-- Name: sp_get_dashboard_kpis(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_get_dashboard_kpis() RETURNS TABLE(metric_key text, numeric_value numeric, text_value text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_total_rev        NUMERIC;
    v_total_gp         NUMERIC;
    v_halal_rev        NUMERIC;
    v_top_cat          TEXT;
    v_top_cat_rev      NUMERIC;
BEGIN
    -- Total Revenue + Gross Profit (calculated from actual transactions)
    WITH product_metrics AS (
        SELECT 
            p.product_id,
            COALESCE(SUM(ti.line_total_lkr), 0) AS revenue,
            COALESCE(SUM(ti.quantity * COALESCE(po.unit_cost_lkr, p.cost_price_lkr, 0)), 0) AS cogs,
            p.is_halal
        FROM products p
        LEFT JOIN transaction_items ti ON p.product_id = ti.product_id
        LEFT JOIN transactions t ON ti.txn_id = t.txn_id
        LEFT JOIN purchase_orders po ON p.product_id = po.product_id
        GROUP BY p.product_id, p.is_halal
    )
    SELECT 
        COALESCE(SUM(revenue), 0),
        COALESCE(SUM(revenue - cogs), 0)
    INTO v_total_rev, v_total_gp
    FROM product_metrics;

    -- Top Category (calculated from actual transactions)
    WITH category_metrics AS (
        SELECT 
            p.category,
            COALESCE(SUM(ti.line_total_lkr), 0) AS revenue
        FROM products p
        LEFT JOIN transaction_items ti ON p.product_id = ti.product_id
        LEFT JOIN transactions t ON ti.txn_id = t.txn_id
        GROUP BY p.category
    )
    SELECT category, revenue
    INTO v_top_cat, v_top_cat_rev
    FROM category_metrics
    WHERE category IS NOT NULL
    ORDER BY revenue DESC
    LIMIT 1;

    -- Halal Revenue (calculated from actual transactions)
    WITH halal_metrics AS (
        SELECT 
            COALESCE(SUM(ti.line_total_lkr), 0) AS revenue
        FROM products p
        LEFT JOIN transaction_items ti ON p.product_id = ti.product_id
        LEFT JOIN transactions t ON ti.txn_id = t.txn_id
        WHERE p.is_halal = TRUE
    )
    SELECT revenue INTO v_halal_rev
    FROM halal_metrics;

    -- Return all KPIs as rows
    RETURN QUERY VALUES
        ('total_revenue',       v_total_rev,    NULL::TEXT),
        ('total_gross_profit',  v_total_gp,     NULL::TEXT),
        ('overall_gp_margin',   ROUND(CASE WHEN v_total_rev > 0 THEN (v_total_gp / v_total_rev) * 100 ELSE 0 END, 1), NULL::TEXT),
        ('avg_cart_size',       (SELECT ROUND(AVG(avg_cart_size_lkr)::NUMERIC, 2) FROM customers), NULL::TEXT),
        ('active_customers',    (SELECT COUNT(*)::NUMERIC FROM customers), NULL::TEXT),
        ('low_stock_alerts',    (SELECT COUNT(*)::NUMERIC FROM products WHERE stock_level < reorder_point), NULL::TEXT),
        ('top_category',        NULL::NUMERIC, v_top_cat),
        ('top_category_revenue',v_top_cat_rev,  NULL::TEXT),
        ('halal_revenue_pct',   ROUND(CASE WHEN v_total_rev > 0 THEN (v_halal_rev / v_total_rev) * 100 ELSE 0 END, 1), NULL::TEXT),
        ('gold_members',        (SELECT COUNT(*)::NUMERIC FROM customers WHERE loyalty_tier = 'Gold'), NULL::TEXT),
        ('total_transactions',  (SELECT COUNT(*)::NUMERIC FROM transactions), NULL::TEXT);
END;
$$;


ALTER FUNCTION public.sp_get_dashboard_kpis() OWNER TO postgres;

--
-- TOC entry 265 (class 1255 OID 344979)
-- Name: sp_get_top10_products(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_get_top10_products() RETURNS TABLE(rank integer, product_name text, category text, brand text, revenue_ytd numeric, gross_profit_ytd numeric, gp_margin_pct numeric, units_sold_ytd integer, is_halal boolean, avg_price_lkr numeric, stock_level integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH product_metrics AS (
        SELECT 
            p.product_id,
            p.product_name,
            p.category,
            p.brand,
            p.is_halal,
            p.stock_level,
            -- Calculate actual revenue and units sold from transactions
            COALESCE(SUM(ti.line_total_lkr), 0) AS actual_revenue,
            COALESCE(SUM(ti.quantity)::INTEGER, 0) AS actual_units_sold,
            -- Calculate average selling price
            CASE 
                WHEN COALESCE(SUM(ti.quantity), 0) > 0 
                THEN COALESCE(SUM(ti.line_total_lkr), 0) / COALESCE(SUM(ti.quantity), 0)
                ELSE 0 
            END AS actual_avg_price,
            -- Calculate cost of goods sold using purchase order costs
            COALESCE(SUM(ti.quantity * COALESCE(po.unit_cost_lkr, p.cost_price_lkr, 0)), 0) AS cogs
        FROM products p
        LEFT JOIN transaction_items ti ON p.product_id = ti.product_id
        LEFT JOIN transactions t ON ti.txn_id = t.txn_id
        LEFT JOIN purchase_orders po ON p.product_id = po.product_id
        GROUP BY p.product_id, p.product_name, p.category, p.brand, p.is_halal, p.stock_level
    )
    SELECT
        ROW_NUMBER() OVER (ORDER BY pm.actual_revenue DESC)::INT AS rank,
        pm.product_name::TEXT,
        pm.category::TEXT,
        pm.brand::TEXT,
        ROUND(pm.actual_revenue::NUMERIC, 2) AS revenue_ytd,
        ROUND((pm.actual_revenue - pm.cogs)::NUMERIC, 2) AS gross_profit_ytd,
        ROUND(
            CASE 
                WHEN pm.actual_revenue > 0 
                THEN ((pm.actual_revenue - pm.cogs) / pm.actual_revenue * 100)
                ELSE 0 
            END::NUMERIC, 2
        ) AS gp_margin_pct,
        pm.actual_units_sold AS units_sold_ytd,
        pm.is_halal,
        ROUND(pm.actual_avg_price::NUMERIC, 2) AS avg_price_lkr,
        pm.stock_level
    FROM product_metrics pm
    ORDER BY pm.actual_revenue DESC
    LIMIT 10;
END;
$$;


ALTER FUNCTION public.sp_get_top10_products() OWNER TO postgres;

--
-- TOC entry 267 (class 1255 OID 344980)
-- Name: sp_insightiq_query(text, text, text[], text[], text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sp_insightiq_query(p_table text, p_join_table text, p_dimensions text[], p_measures text[], p_filters_json text, p_limit integer DEFAULT 50, p_order_by text DEFAULT NULL::text, p_order_dir text DEFAULT 'DESC'::text, p_agg_functions_json text DEFAULT '{}'::text) RETURNS SETOF json
    LANGUAGE plpgsql
    AS $$
DECLARE
    -- Column metadata lookup: field_key → actual SQL column expression
    v_col_map    JSONB;
    -- Join table column map
    v_join_map   JSONB;
    v_agg_fns    JSONB;
    v_filters    JSONB;

    v_select     TEXT[];
    v_group_by   TEXT[];
    v_where      TEXT[];
    v_join_sql   TEXT := '';
    v_order_sql  TEXT := '';
    v_sql        TEXT;
    v_from_sql   TEXT := '';

    v_dim        TEXT;
    v_msr        TEXT;
    v_col        TEXT;
    v_agg        TEXT;
    v_flt        JSONB;
    v_flt_field  TEXT;
    v_flt_op     TEXT;
    v_flt_val    TEXT;
    v_order_col  TEXT;
    v_limit_safe INT;
BEGIN
    -- ── Sanitise limit ─────────────────────────────────────
    v_limit_safe := LEAST(COALESCE(p_limit, 50), 1000);

    -- ── Parse JSON inputs ─────────────────────────────────
    v_agg_fns := COALESCE(p_agg_functions_json::JSONB, '{}');
    v_filters := COALESCE(p_filters_json::JSONB, '[]');

    -- ── Column whitelist maps ─────────────────────────────
    v_col_map := CASE p_table
        WHEN 'customers' THEN '{
            "gender":"gender","age_group":"age_group","religion":"religion",
            "area":"area","loyalty_tier":"loyalty_tier",
            "preferred_category":"preferred_category",
            "avg_cart_size_lkr":"avg_cart_size_lkr",
            "visits_per_month":"visits_per_month",
            "total_spend_ytd":"total_spend_ytd","join_date":"join_date"
        }'::JSONB
        WHEN 'products' THEN '{
            "product_name":"product_name","category":"category",
            "sub_category":"sub_category","brand":"brand",
            "is_halal":"is_halal","is_organic":"is_organic","is_local":"is_local",
            "avg_price_lkr":"avg_price_lkr","cost_price_lkr":"cost_price_lkr",
            "units_sold_ytd":"units_sold_ytd","revenue_ytd":"revenue_ytd",
            "stock_level":"stock_level","reorder_point":"reorder_point",
            "gross_profit_ytd":"revenue_ytd - (units_sold_ytd * cost_price_lkr)"
        }'::JSONB
        WHEN 'transactions' THEN '{
            "txn_month":"txn_month","day_of_week":"TRIM(day_of_week)",
            "time_of_day":"time_of_day","payment_method":"payment_method",
            "total_value_lkr":"total_value_lkr","discount_lkr":"discount_lkr",
            "num_items":"num_items","basket_count":"COUNT(transactions.txn_id)"
        }'::JSONB
        WHEN 'departments' THEN '{
            "dept_name":"dept_name","floor_zone":"floor_zone","manager":"manager",
            "staff_count":"staff_count","revenue_target":"revenue_target",
            "actual_revenue":"actual_revenue","shrinkage_pct":"shrinkage_pct"
        }'::JSONB
        WHEN 'branches' THEN '{
            "branch_name":"branch_name","city":"city","region":"region",
            "manager":"manager","branch_size_sqft":"branch_size_sqft",
            "daily_footfall":"daily_footfall","opened_year":"opened_year"
        }'::JSONB
        WHEN 'suppliers' THEN '{
            "supplier_name":"supplier_name","origin_country":"origin_country",
            "halal_certified":"halal_certified","organic_certified":"organic_certified",
            "lead_time_days":"lead_time_days",
            "on_time_delivery_pct":"on_time_delivery_pct",
            "total_orders_ytd":"total_orders_ytd","spend_ytd":"spend_ytd"
        }'::JSONB
        WHEN 'promotions' THEN '{
            "promo_name":"promo_name","promo_type":"promo_type",
            "target_segment":"target_segment","start_date":"start_date",
            "end_date":"end_date","discount_pct":"discount_pct",
            "redemptions":"redemptions","revenue_uplift_lkr":"revenue_uplift_lkr",
            "roi_pct":"roi_pct"
        }'::JSONB
        WHEN 'inventory' THEN '{
            "sku":"sku","warehouse_zone":"warehouse_zone",
            "quantity_on_hand":"quantity_on_hand",
            "quantity_on_order":"quantity_on_order",
            "days_of_supply":"days_of_supply","shelf_life_days":"shelf_life_days",
            "expiry_risk_units":"expiry_risk_units",
            "last_received_date":"last_received_date"
        }'::JSONB
        ELSE '{}'::JSONB
    END;

    -- ── JOIN columns (extra fields unlocked by joining) ────
    v_join_map := CASE
        WHEN p_join_table = 'transactions' AND p_table IN ('products','customers','branches') THEN '{
            "txn_month":"transactions.txn_month",
            "day_of_week":"TRIM(transactions.day_of_week)",
            "time_of_day":"transactions.time_of_day",
            "payment_method":"transactions.payment_method",
            "total_value_lkr":"transactions.total_value_lkr",
            "discount_lkr":"transactions.discount_lkr",
            "basket_count":"COUNT(DISTINCT transactions.txn_id)",
            "line_total":"SUM(_ti.line_total_lkr)",
            "quantity_sold":"SUM(_ti.quantity)",
            "revenue_calculated":"SUM(_ti.line_total_lkr)",
            "cogs_calculated":"SUM(_ti.quantity * COALESCE(po.unit_cost_lkr, products.cost_price_lkr, 0))",
            "gross_profit_calculated":"SUM(_ti.line_total_lkr) - SUM(_ti.quantity * COALESCE(po.unit_cost_lkr, products.cost_price_lkr, 0))",
            "gross_profit_ytd":"SUM(_ti.line_total_lkr) - SUM(_ti.quantity * COALESCE(po.unit_cost_lkr, products.cost_price_lkr, 0))",
            "gp_margin_calculated":"CASE WHEN SUM(_ti.line_total_lkr) > 0 THEN ((SUM(_ti.line_total_lkr) - SUM(_ti.quantity * COALESCE(po.unit_cost_lkr, products.cost_price_lkr, 0))) / SUM(_ti.line_total_lkr) * 100) ELSE 0 END"
        }'::JSONB
        WHEN p_join_table = 'products' THEN '{
            "product_name":"products.product_name",
            "category":"products.category","brand":"products.brand",
            "revenue_ytd":"products.revenue_ytd",
            "is_halal":"products.is_halal",
            "revenue_calculated":"SUM(_ti.line_total_lkr)",
            "cogs_calculated":"SUM(_ti.quantity * COALESCE(po.unit_cost_lkr, products.cost_price_lkr, 0))",
            "gross_profit_calculated":"SUM(_ti.line_total_lkr) - SUM(_ti.quantity * COALESCE(po.unit_cost_lkr, products.cost_price_lkr, 0))",
            "gross_profit_ytd":"SUM(_ti.line_total_lkr) - SUM(_ti.quantity * COALESCE(po.unit_cost_lkr, products.cost_price_lkr, 0))",
            "gp_margin_calculated":"CASE WHEN SUM(_ti.line_total_lkr) > 0 THEN ((SUM(_ti.line_total_lkr) - SUM(_ti.quantity * COALESCE(po.unit_cost_lkr, products.cost_price_lkr, 0))) / SUM(_ti.line_total_lkr) * 100) ELSE 0 END"
        }'::JSONB
        ELSE '{}'::JSONB
    END;

    -- ── Build FROM and JOIN SQL with purchase_orders for COGS ──
    IF p_join_table IS NOT NULL AND p_join_table <> '' THEN
        v_join_sql := CASE
            WHEN p_table = 'products'  AND p_join_table = 'transactions' THEN
                'LEFT JOIN transaction_items _ti ON _ti.product_id = products.product_id ' ||
                'LEFT JOIN transactions ON transactions.txn_id = _ti.txn_id ' ||
                'LEFT JOIN purchase_orders po ON po.product_id = products.product_id'
            WHEN p_table = 'customers' AND p_join_table = 'transactions' THEN
                'LEFT JOIN transactions ON transactions.customer_id = customers.customer_id ' ||
                'LEFT JOIN transaction_items _ti ON _ti.txn_id = transactions.txn_id ' ||
                'LEFT JOIN products ON products.product_id = _ti.product_id ' ||
                'LEFT JOIN purchase_orders po ON po.product_id = products.product_id'
            WHEN p_table = 'branches'  AND p_join_table = 'transactions' THEN
                'LEFT JOIN transactions ON transactions.branch_id = branches.branch_id ' ||
                'LEFT JOIN transaction_items _ti ON _ti.txn_id = transactions.txn_id ' ||
                'LEFT JOIN products ON products.product_id = _ti.product_id ' ||
                'LEFT JOIN purchase_orders po ON po.product_id = products.product_id'
            WHEN p_table = 'transactions' AND p_join_table = 'products' THEN
                'LEFT JOIN transaction_items _ti ON _ti.txn_id = transactions.txn_id ' ||
                'LEFT JOIN products ON products.product_id = _ti.product_id ' ||
                'LEFT JOIN purchase_orders po ON po.product_id = products.product_id'
            WHEN p_table = 'transactions' AND p_join_table = 'customers' THEN
                'LEFT JOIN customers ON customers.customer_id = transactions.customer_id'
            WHEN p_table = 'transactions' AND p_join_table = 'branches' THEN
                'LEFT JOIN branches ON branches.branch_id = transactions.branch_id'
            ELSE ''
        END;
    END IF;

    -- ── Build SELECT ───────────────────────────────────────
    v_select  := '{}';
    v_group_by := '{}';

    FOREACH v_dim IN ARRAY p_dimensions LOOP
        -- Resolve column from primary or join map
        v_col := COALESCE(
            (v_col_map  ->> v_dim),
            (v_join_map ->> v_dim)
        );
        IF v_col IS NULL THEN
            RAISE EXCEPTION 'Unknown dimension field: %', v_dim;
        END IF;
        v_select   := array_append(v_select, 'CAST(' || v_col || ' AS TEXT) AS "' || v_dim || '"');
        v_group_by := array_append(v_group_by, v_col);
    END LOOP;

    FOREACH v_msr IN ARRAY p_measures LOOP
        v_col := COALESCE(
            (v_col_map  ->> v_msr),
            (v_join_map ->> v_msr)
        );
        IF v_col IS NULL THEN
            RAISE EXCEPTION 'Unknown measure field: %', v_msr;
        END IF;
        
        -- Check for calculated fields that shouldn't get extra aggregation
        IF v_col IN ('gross_profit_calculated', 'gp_margin_calculated', 'revenue_calculated', 'cogs_calculated', 'gross_profit_ytd') THEN
            -- These are already aggregated expressions
            v_select := array_append(v_select, v_col || ' AS "' || v_msr || '"');
        ELSE
            v_agg := UPPER(COALESCE(v_agg_fns ->> v_msr, 'SUM'));
            IF v_agg NOT IN ('SUM','AVG','COUNT','MIN','MAX') THEN v_agg := 'SUM'; END IF;
            -- If column already has an aggregate, use as-is
            IF v_col ~ '^(SUM|AVG|COUNT|MIN|MAX)\(' OR v_col ~ '^COUNT\(DISTINCT' THEN
                v_select := array_append(v_select, v_col || ' AS "' || v_msr || '"');
            ELSE
                v_select := array_append(v_select, v_agg || '(' || v_col || ') AS "' || v_msr || '"');
            END IF;
        END IF;
    END LOOP;

    -- ── Build WHERE ────────────────────────────────────────
    v_where := '{}';
    FOR v_flt IN SELECT * FROM jsonb_array_elements(v_filters) LOOP
        v_flt_field := v_flt->>'field';
        v_flt_op    := UPPER(TRIM(v_flt->>'op'));
        v_flt_val   := v_flt->>'value';

        IF v_flt_val IS NULL OR v_flt_val = '' THEN CONTINUE; END IF;
        IF v_flt_op NOT IN ('=','!=','>','<','>=','<=','IN','LIKE') THEN CONTINUE; END IF;

        v_col := COALESCE(
            (v_col_map  ->> v_flt_field),
            (v_join_map ->> v_flt_field)
        );
        IF v_col IS NULL THEN CONTINUE; END IF;

        IF v_flt_op = 'IN' THEN
            v_where := array_append(v_where,
                v_col || ' IN (' ||
                (SELECT string_agg(quote_literal(TRIM(item)), ',')
                 FROM unnest(string_to_array(v_flt_val, ',')) AS item) ||
                ')');
        ELSIF v_flt_op = 'LIKE' THEN
            v_where := array_append(v_where, v_col || ' ILIKE ' || quote_literal('%' || v_flt_val || '%'));
        ELSIF v_flt_val IN ('true','false') THEN
            v_where := array_append(v_where, v_col || ' = ' || v_flt_val);
        ELSE
            v_where := array_append(v_where, v_col || ' ' || v_flt_op || ' ' || quote_literal(v_flt_val));
        END IF;
    END LOOP;

    -- ── Build ORDER BY ─────────────────────────────────────
    v_order_col := NULL;
    IF p_order_by IS NOT NULL AND p_order_by <> '' THEN
        v_order_col := COALESCE(
            (v_col_map  ->> p_order_by),
            (v_join_map ->> p_order_by)
        );
    END IF;
    IF v_order_col IS NULL AND array_length(p_measures, 1) > 0 THEN
        v_order_col := COALESCE(
            (v_col_map  ->> p_measures[1]),
            (v_join_map ->> p_measures[1])
        );
    END IF;

    IF v_order_col IS NOT NULL THEN
        -- Check if it's a calculated field
        IF v_order_col IN ('gross_profit_calculated', 'gp_margin_calculated', 'revenue_calculated', 'cogs_calculated', 'gross_profit_ytd') THEN
            v_order_sql := 'ORDER BY ' || v_order_col || ' ' || CASE WHEN UPPER(p_order_dir) = 'ASC' THEN 'ASC' ELSE 'DESC' END;
        ELSE
            v_agg := UPPER(COALESCE(v_agg_fns ->> COALESCE(p_order_by, p_measures[1]), 'SUM'));
            IF v_agg NOT IN ('SUM','AVG','COUNT','MIN','MAX') THEN v_agg := 'SUM'; END IF;
            IF v_order_col ~ '^(SUM|AVG|COUNT|MIN|MAX)\(' THEN
                v_order_sql := 'ORDER BY ' || v_order_col || ' ' || CASE WHEN UPPER(p_order_dir) = 'ASC' THEN 'ASC' ELSE 'DESC' END;
            ELSE
                v_order_sql := 'ORDER BY ' || v_agg || '(' || v_order_col || ') ' || CASE WHEN UPPER(p_order_dir) = 'ASC' THEN 'ASC' ELSE 'DESC' END;
            END IF;
        END IF;
    END IF;

    -- ── Assemble final SQL ─────────────────────────────────
    v_sql := 'SELECT row_to_json(t) FROM ('
        || 'SELECT ' || array_to_string(v_select, ', ')
        || ' FROM ' || quote_ident(p_table)
        || CASE WHEN v_join_sql <> '' THEN ' ' || v_join_sql ELSE '' END
        || CASE WHEN array_length(v_where, 1) > 0 THEN ' WHERE ' || array_to_string(v_where, ' AND ') ELSE '' END
        || CASE WHEN array_length(v_group_by, 1) > 0 AND array_length(p_measures, 1) > 0
                THEN ' GROUP BY ' || array_to_string(v_group_by, ', ') ELSE '' END
        || CASE WHEN v_order_sql <> '' THEN ' ' || v_order_sql ELSE '' END
        || ' LIMIT ' || v_limit_safe
        || ') t';

    -- RAISE NOTICE 'SQL: %', v_sql;
    
    RETURN QUERY EXECUTE v_sql;
END;
$$;


ALTER FUNCTION public.sp_insightiq_query(p_table text, p_join_table text, p_dimensions text[], p_measures text[], p_filters_json text, p_limit integer, p_order_by text, p_order_dir text, p_agg_functions_json text) OWNER TO postgres;

